import { useCallback, useEffect, useState } from 'react'
import type { ExpenseViewModel, NewExpense, SubmitExpenseResult } from '../../application/ExpenseViewModel'
import { useExpenseUseCases } from '../useExpenseUseCases/useExpenseUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpenseUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async () => {
    try {
      setExpenses(await listExpenses.execute())
      setError(null)
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not load expenses')
    } finally {
      setLoading(false)
    }
  }, [listExpenses])

  useEffect(() => {
    void load()
  }, [load])

  const submit = async (expense: NewExpense): Promise<SubmitExpenseResult> => {
    const result = await submitExpense.execute(expense)
    if (result.type === 'submitted') await load()
    return result
  }

  return { expenses, loading, error, submit }
}
